/* page / game -> accent colour (see styles/accents.css). Home keeps the original green. */
export const ACCENT_OF = { home: 'green', login: 'orange', signup: 'blue', css: 'purple', sel: 'pink', quiz: 'yellow' };

/* shades used to recolour the game *content* (the CSS values the player has to type) */
export const SHADES = {
  green: { ac: '#22c55e', ac2: '#86efac', ac3: '#4ade80', dk: '#14532d', acL: '#16a34a', ac2L: '#15803d', hue: 140 },
  orange: { ac: '#f97316', ac2: '#fdba74', ac3: '#fb923c', dk: '#7c2d12', acL: '#ea580c', ac2L: '#c2410c', hue: 25 },
  blue: { ac: '#3b82f6', ac2: '#93c5fd', ac3: '#60a5fa', dk: '#1e3a8a', acL: '#2563eb', ac2L: '#1d4ed8', hue: 217 },
  purple: { ac: '#a855f7', ac2: '#d8b4fe', ac3: '#c084fc', dk: '#581c87', acL: '#9333ea', ac2L: '#7e22ce', hue: 271 },
  pink: { ac: '#ec4899', ac2: '#f9a8d4', ac3: '#f472b6', dk: '#831843', acL: '#db2777', ac2L: '#be185d', hue: 330 },
  yellow: { ac: '#eab308', ac2: '#fde047', ac3: '#facc15', dk: '#713f12', acL: '#ca8a04', ac2L: '#a16207', hue: 48 },
};
